 const transform=(arr,len=24)=>{let run=0;return Array.from({length:24},(_,h)=>{run+=arr[h];return h<len?(mode==='cumulative'?run:arr[h]):null;});};
 series.push({name:'2027 demo',color:'#c00000',data:transform(a,n),width:3});
