 const max=Math.max(1,...series.flatMap(s=>s.data.filter(x=>x!==null))),W=840,H=280,L=65,T=18,R=20,B=45,x=h=>L+(mode==='cumulative'?h+1:h+.5)*(W-L-R)/24,y=v=>T+(1-v/max)*(H-T-B);
