 for(let i=0;i<=4;i++){const v=max*i/4,yy=y(v);svg+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+yy+'" y2="'+yy+'" stroke="#e3e8ef"/><text x="'+(L-10)+'" y="'+(yy+4)+'" text-anchor="end" font-size="11" fill="#56657a">'+(key==='gifts'?compact(v):'$'+compact(v/100))+'</text>';}
