 for(const s of [...series].reverse()){if(mode==='hourly'&&s===series[0]){s.data.forEach((v,h)=>{if(v!==null)svg+='<rect x="'+(x(h)-8)+'" y="'+y(v)+'" width="16" height="'+(y(0)-y(v))+'" fill="'+s.color+'" opacity=".8"/>';});}else svg+='<polyline fill="none" stroke="'+s.color+'" stroke-width="'+s.width+'" '+(s.dash?'stroke-dasharray="'+s.dash+'"':'')+' points="'+s.data.map((v,h)=>v===null?'':x(h)+','+y(v)).filter(Boolean).join(' ')+'"/>';}
