 const text=state.period==='vip'?'Pre-launch gifts are shown separately. Day-only comparisons and recognition exclude VIP activity.':gp===null?'Live totals are available; completed-hour pacing appears after the first hour.':('Gifts are '+deltaText(gp)+' versus the configured historical average; online dollars are '+deltaText(dp)+'. Recent gift momentum: '+D.classification(mom)+'.');
