  if(!done){const partialRows=D.rows(options({channel,period:'day'})).filter(g=>g.t>=h*3600&&g.t<end),v=online?D.sum(partialRows,g=>g.cents):partialRows.length;rows.push([hourLabel(h),badge(partial?'Partial':'Upcoming'),partial?fmt(v):'--',...Array(online?12:14).fill('--')]);continue;}
  const a=actual.map(r=>r[key]),ma=D.mean(a.slice(Math.max(0,h-2),h+1)),moment=D.momentum(a,base,h+1),share=base?D.ratio(bCum,D.sum(base)):null,forecast=share>=cfg.gate?vip[key]+cum/share:null;
  const row=[hourLabel(h),badge(D.classification(moment)),fmt(actual[h][key]),base?fmt(base[h]):'--',base?(online?money(actual[h][key]-base[h]):signed(actual[h][key]-base[h])):'--',fmt(cum),base?fmt(bCum):'--',base?(online?money(cum-bCum):signed(cum-bCum)):'--',diffCell(delta(cum,base?bCum:null)),diffCell(delta(cum,pCum)),fmt(ma),moment===null?'--':dec(moment)+'x',forecast===null?'Withheld':fmt(forecast),fmt(vip[key]+cum),actual[h].gifts?money(actual[h].cents/actual[h].gifts):'--'];
