function historyMatrix(m){const key=state.trendMetric,ch=key==='gifts'?state.channel:'online',fmt=key==='gifts'?num:money,base=historicalSeries(key,ch),cur=D.hourly(options({channel:ch})),hist=cfg.compare.map(year=>D.hourly(options({channel:ch,year})));return '<details><summary>Exact hour-by-hour historical comparison</summary>'+notice('Current values stop at the last completed hour. Historical columns retain the full completed day; future current hours remain blank.')+table(['Hour','2027 demo',...cfg.compare.map(String),'Configured average'],Array.from({length:24},(_,h)=>[hourLabel(h),h<m.n?fmt(cur[h][key]):'--',...hist.map(a=>fmt(a[h][key])),base?fmt(base[h]):'--']),'Historical hourly comparison')+'</details>';}
function scenarios(m){const fs=[m.gf,m.df],names=['Historical pace (readiness gated)','Current run rate','Last 3 hours','Stretch +10% of future recent pace'],keys=['projection','run','recent','stretch'];const rows=names.map((name,i)=>[name,fs[0].ready||i>0?num(fs[0][keys[i]]):'Withheld',fs[1].ready||i>0?money(fs[1][keys[i]]):'Withheld',['Observed day / historical day share, plus VIP once if included.','Average observed day rate continues.','Recent completed-hour average continues.','Only the remaining hours receive a 10% uplift.'][i]]);return table(['Scenario','Final gifts','Final online dollars','Assumption'],rows,'Closing scenario comparison')+notice('Scenarios are alternatives, not confidence bounds. All forecasts use completed hours and are floored at already observed totals. No unique-donor forecast or offline-dollar extrapolation.')+notice('Historical-shape spread: '+(m.gf.ready?num(m.gf.low)+' - '+num(m.gf.high)+' gifts':'not yet available')+'; '+(m.df.ready?money(m.df.low)+' - '+money(m.df.high)+' online dollars':'online dollars not yet available')+'. This is the spread of selected historical shapes, not a statistical confidence interval.');}
function dayparts(m){const defs=[['Overnight',0,7],['Morning',7,12],['Afternoon',12,17],['Evening',17,21],['Final push',21,24]],online=D.hourly(options({channel:'online'})),data=[];
 if(state.period==='campaign'){const s=D.stats(D.rows(options({period:'vip'}))),o=D.stats(D.rows(options({period:'vip',channel:'online'})));data.push(['VIP (separate)',badge('Pre-launch'),num(s.gifts),'--',money(o.cents),'--']);}
 for(const [name,start,end] of defs){const to=Math.min(end,m.n),count=Math.max(0,to-start),g=D.sum(m.day.slice(start,Math.max(start,to)),r=>r.gifts),d=D.sum(online.slice(start,Math.max(start,to)),r=>r.cents),gb=m.b?D.sum(m.b.slice(start,Math.max(start,to))):null,db=m.bd?D.sum(m.bd.slice(start,Math.max(start,to))):null;data.push([name+' ('+start+':00-'+end+':00)',badge(m.n>=end?'Complete':m.n>start?'In progress':'Upcoming'),count?num(g):'--',count?diffCell(delta(g,gb)):'--',count?money(d):'--',count?diffCell(delta(d,db)):'--']);}
 return table(['Daypart','Status','Gifts','Vs average','Online dollars','Vs average'],data,'Daypart summary')+notice('Workbook daypart boundaries are retained: midnight-7 AM, 7 AM-noon, noon-5 PM, 5-9 PM, 9 PM-midnight. VIP is displayed separately instead of being mixed into overnight pace. Only elapsed, completed hours are compared.');}
