 let html=panel('Historical comparisons','<div class="toolbar"><label>Metric<select id="trendMetric"><option value="gifts" '+(state.trendMetric==='gifts'?'selected':'')+'>Gifts ('+channelLabel()+')</option><option value="cents" '+(state.trendMetric==='cents'?'selected':'')+'>Online dollars only</option></select></label><label>Chart view<select id="trendMode"><option value="cumulative" '+(state.mode==='cumulative'?'selected':'')+'>Cumulative</option><option value="hourly" '+(state.mode==='hourly'?'selected':'')+'>Hourly</option></select></label></div><fieldset><legend>Historical lines to display (fictional)</legend><div class="checkboxes">'+D.YEARS.map(y=>'<label><input type="checkbox" data-overlay="'+y+'" '+(cfg.compare.includes(y)?'checked':'')+'>'+y+'</label>').join('')+'</div></fieldset>'+plot(m,state.trendMetric)+notice('Average baselines: gifts '+cfg.giftYears.join(', ')+'; online dollars '+cfg.dollarYears.join(', ')+'. Explicit benchmark: '+prior+'. Baselines are configured separately from displayed lines.'));
